    pub fn init() SemanticControlSummary {
        return .{
            .has_mutation = false,
            .has_if = false,
            .has_while = false,
            .has_for = false,
            .has_try = false,
            .has_error_union = false,
            .assignment_nodes = 0,
            .arithmetic_nodes = 0,
            .logical_nodes = 0,
            .bit_nodes = 0,
            .loop_nodes = 0,
        };
    }
};

